import sys

def main():
    data = [line.strip() for line in sys.stdin if line.strip() != '']
    i = 0
    while i + 1 < len(data):
        try:
            dividend = int(data[i])
            divisor = int(data[i + 1])
        except ValueError:
            print("NumberFormatException: Invalid input. Please enter integers only.")
        else:
            try:
                result = dividend // divisor
                print(f"Result: {result}")
            except ZeroDivisionError:
                print("ArithmeticException: Division by zero is not allowed.")
        i += 2

if __name__ == "__main__":
    main()
